pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.prank(caller);
        bool ok;
        try c.setL1BlockValues(
            0, 0, 0, bytes32(0), 0, bytes32(0), 0, 0
        ) {
            ok = true;
        } catch {
            ok = false;
        }
        bool expectedOk = (caller == c.DEPOSITOR_ACCOUNT());
        assertTrue(ok == expectedOk);
    }
}

